where not exists (select 1 from auth.users where email='buyer02@sellerport.app');
select gen_random_uuid(),'a0000000-0000-4000-8000-000000000003','{"sub":"a0000000-0000-4000-8000-000000000003","email":"buyer02@sellerport.app","email_verified":true}'::jsonb,'email','buyer02@sellerport.app',now(),now(),now()
where exists (select 1 from auth.users where id='a0000000-0000-4000-8000-000000000003') and not exists (select 1 from auth.identities where provider='email' and provider_id='buyer02@sellerport.app');
